// escape HTML special characters in text.
func escape(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&quot;")
		default:
			b.WriteByte(s[i])
		}
	}
	return b.String()
}

func isWord(b byte) bool {
	return b >= 'a' && b <= 'z' || b >= 'A' && b <= 'Z' || b >= '0' && b <= '9'
}

// renderInline renders inline markup. noLinks disables link parsing (inside link text).
func renderInline(s string, noLinks bool) string {
	s = prebreak(s)
	toks := tokenize(s, noLinks)
	return resolveEmph(toks)
}
