func resolveEmph(toks []tok) string {
	type opener struct {
		ch    byte
		start int // index in out of the first remaining char of this run
		n     int // remaining chars
	}
	var out []string
	var stack []opener

	for _, t := range toks {
		switch t.kind {
		case tText, tCode:
			out = append(out, t.s)
		case tDelim:
			matched := false
			if t.close {
				for j := len(stack) - 1; j >= 0; j-- {
					if stack[j].ch != t.ch {
						continue
					}
					o := stack[j]
					c := 1
					if o.n >= 2 && t.n >= 2 {
						c = 2
					}
					tag := "<em>"
					if c == 2 {
						tag = "<strong>"
					}
					content := strings.Join(out[o.start+o.n:], "")
					// rewrite opener tail with the tag; delta chunks
					delta := 1 - c
					consumeStart := o.start + o.n - c
					out = append(append(out[:consumeStart], tag), out[o.start+o.n:]...)
					// update stack: remove j, shift indices
					for m := range stack {
						if stack[m].start >= consumeStart {
							stack[m].start += delta
						}
					}
					stack = append(stack[:j], stack[j+1:]...)
					if o.n-c >= 1 {
						// leftover opener remains at o.start
						stack = append(stack, opener{ch: t.ch, start: o.start, n: o.n - c})
						// hmm — order in stack matters (topmost = most recent). The leftover is at the same position as the old o; to preserve relative order it should be inserted at j's position.
					}
					...
				}
			}
			// emit closer chars
			...
		}
	}
}
```

