package md

import (
	"strings"
)

// HTML-escape &, <, >, and ".
func escape(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&quot;")
		default:
			b.WriteByte(s[i])
		}
	}
	return b.String()
}

func isWord(b byte) bool {
	return ('a' <= b && b <= 'z') || ('A' <= b && b <= 'Z') || ('0' <= b && b <= '9')
}

// prebreak implements hard breaks by trailing spaces:
// on every line except the last, 2 or more trailing spaces become "<br />",
// and trailing spaces on every line are stripped.
func prebreak(s string) string {
	lines := strings.Split(s, "\n")
	for i, l := range lines {
		t := strings.TrimRight(l, " ")
		if len(l)-len(t) >= 2 && i < len(lines)-1 {
			t += "<br />"
		}
		lines[i] = t
	}
	return strings.Join(lines, "\n")
}

// renderInline renders inline markup within a single block.
func renderInline(s string, noLinks bool) string {
	return resolveEmph(tokenize(prebreak(s), noLinks))
}

const (
	tText = iota
	tCode
	tDelim
)

type tok struct {
	kind  int
	s     string
	ch    byte
	n     int
	open  bool
	close bool
}

var escapeChars = "`*_{}[]()#+-.!<>"

func tokenize(s string, noLinks bool) []tok {
	var toks []tok
	var cur strings.Builder
	flush := func() {
		if cur.Len() > 0 {
			toks = append(toks, tok{kind: tText, s: cur.String()})
			cur.Reset()
		}
	}
	for i := 0; i < len(s); {
		switch c := s[i]; {
		case c == '\\':
			flush()
			if i+1 < len(s) && strings.ContainsRune(escapeChars, rune(s[i+1])) {
				cur.WriteString(escape(s[i+1 : i+2]))
				i += 2
			} else if i+1 < len(s) && s[i+1] == '\n' && i+2 < len(s) {
				cur.WriteString("<br />\n")
				i += 2
			} else {
				cur.WriteByte('\\')
				i++
			}
		case c == '`':
			flush()
			k := 0
			for i+k < len(s) && s[i+k] == '`' {
				k++
			}
			j, found := i+k, -1
			for j < len(s) {
				if s[j] != '`' {
					j++
					continue
				}
				m := 0
				for j+m < len(s) && s[j+m] == '`' {
					m++
				}
				if m == k {
					found = j
					break
				}
				j += m
			}
			if found < 0 {
				cur.WriteString(strings.Repeat("`", k))
				i += k
			} else {
				content := s[i+k : found]
				if len(content) >= 2 && content[0] == ' ' && content[len(content)-1] == ' ' &&
